def build_audition_hayek() -> EpisodeCueSheet:
    cues = [
        motif("ha01_rain", "audition", "cambridge_fireplace_rain", gap_after_s=0.25, director_note="1944剑桥雨夜壁炉入戏"),
        dlg("ha02_narrator", "audition", "narrator", "历史旁白", "[solemn] 一九四四年三月，二战炮火还没停息。在剑桥大学一间拉着遮光帘的书房里，一场关乎普通人饭碗、自由与秩序的深夜辩论，正在红茶热气里展开。", acoustic_space="dry", gap_after_s=0.24),
        dlg("ha03_shen", "audition", "reporter_shen", "沈明微", "[curious] 哈耶克教授，您这本小册子刚在伦敦上架就被抢空了，可普通人一听书名就发懵——战后大家只想过上安稳、公平的日子，由国家统一安排生产，错在哪儿了？", gap_after_s=0.22),
        dlg("ha04_lin", "audition", "student_lin", "林致远", "[pushback] 是啊教授！大萧条把那么多工厂整倒闭了，如果我们请最聪明的科学家把全国的粮食、煤炭和学校统筹规划好，难道不比市场乱糟糟地撞大运更高效？", gap_after_s=0.22),
        dlg("ha05_hayek", "audition", "hayek", "哈耶克", "[calmly] 致远，打个最简单的比方。法律就像马路上的红绿灯，它规定大家靠哪边走、红灯停绿灯行；可如果有一天，交警不但管红绿灯，还非要替你决定今天几点出门、必须去哪家馆子吃面——那就不再是秩序，而是替你活着。", gap_after_s=0.24),
        dlg("ha06_chen", "audition", "shopkeeper_chen", "老陈", "[earthy] [chuckles] 哎哟，教授这比方一下说到我心坎里去了！我街口那家小杂货铺，哪天谁捏着全镇的面粉批条，我就算本事再大，也得天天弯腰看人脸色过活！", stability=0.0, gap_after_s=0.24),
        motif("ha07_teacup", "audition", "porcelain_teacup_study", gap_after_s=0.20),
        dlg("ha08_keynes", "audition", "keynes", "凯恩斯", "[warmly] [seriously] 弗里茨，你的担忧我感同身受。可眼下千万人失业、满街工厂熄火，难道政府能袖手旁观？真问题从来不是要不要画线，而是——这条线，究竟该画在哪儿。", gap_after_s=0.50),
    ]
    return EpisodeCueSheet(
        episode_id="AUDITION_HAYEK",
        chapter_number=0,
        title="《1944剑桥夜话：〈通往奴役之路〉思想剧场》六角色试听包",
        mode="audition_pack",
        head_pad_s=0.35,
        tail_pad_s=1.0,
        acts=[act("audition", "1944剑桥夜话试听", "cambridge_wartime_study", bgm_duration_s=60.0)],
        cues=cues,
    )


